using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoastalSurfaceFinish{
const string Dir="Assets/Scenes/Oasis/CoastalTerrain";static CoastalSurfaceFinish(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalSurfaceFinish.request")||EditorApplication.isCompiling)return;File.Delete("CoastalSurfaceFinish.request");Run();}
static float Distance(Vector2 p,Vector2[] line){float d=float.MaxValue;for(int i=0;i<line.Length-1;i++){var e=line[i+1]-line[i];d=Mathf.Min(d,Vector2.Distance(p,line[i]+e*Mathf.Clamp01(Vector2.Dot(p-line[i],e)/e.sqrMagnitude)));}return d;}
static Texture2D BakeNormal(Texture2D source){var rt=RenderTexture.GetTemporary(1024,1024,0,RenderTextureFormat.ARGB32);Graphics.Blit(source,rt);var previous=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1024,1024,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,1024,1024),0,0);image.Apply();RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);var pixels=image.GetPixels();var output=new Color[pixels.Length];for(int y=0;y<1024;y++)for(int x=0;x<1024;x++){float dx=pixels[y*1024+(x+2)%1024].grayscale-pixels[y*1024+(x+1022)%1024].grayscale;float dy=pixels[((y+2)%1024)*1024+x].grayscale-pixels[((y+1022)%1024)*1024+x].grayscale;var n=new Vector3(-dx*3,-dy*3,1).normalized;output[y*1024+x]=new Color(n.x*.5f+.5f,n.y*.5f+.5f,n.z*.5f+.5f,1);}image.SetPixels(output);image.Apply();string path=Dir+"/Crags/Granite Relief Normal.png";File.WriteAllBytes(path,image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.NormalMap;importer.wrapMode=TextureWrapMode.Repeat;importer.maxTextureSize=1024;importer.mipmapEnabled=true;importer.streamingMipmaps=true;foreach(string platform in new[]{"Android","iPhone"})importer.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=1024,format=TextureImporterFormat.ASTC_6x6});importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
static float Height(TerrainData d,Vector3 origin,Vector3 p)=>d.GetInterpolatedHeight(Mathf.Clamp01((p.x-origin.x)/d.size.x),Mathf.Clamp01((p.z-origin.z)/d.size.z))+origin.y;
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Coastal Rocky Terrain");var terrain=root.GetComponentInChildren<Terrain>();var data=terrain.terrainData;string backupPath=Dir+"/Before Surface Finish.asset";var baseline=AssetDatabase.LoadAssetAtPath<TerrainData>(backupPath);if(!baseline){baseline=UnityEngine.Object.Instantiate(data);baseline.name="Terrain before surface refinement";AssetDatabase.CreateAsset(baseline,backupPath);}var old=UnityEngine.Object.Instantiate(data);var line=File.ReadAllLines("FinalEnvironmentRoadReview/CoastalSnappedEdge.txt").Select(s=>{var v=s.Trim('(',')').Split(',');return new Vector2(float.Parse(v[0],System.Globalization.CultureInfo.InvariantCulture),float.Parse(v[1],System.Globalization.CultureInfo.InvariantCulture));}).ToArray();
var normal=BakeNormal(AssetDatabase.LoadAssetAtPath<Texture2D>(Dir+"/Crags/Large Fractured Granite.png"));terrain.materialTemplate.SetTexture("_CliffNormal",normal);EditorUtility.SetDirty(terrain.materialTemplate);var rockMaterial=AssetDatabase.LoadAssetAtPath<Material>(Dir+"/Crags/Shared Large Granite Faces.mat");rockMaterial.SetTexture("_BumpMap",normal);rockMaterial.SetFloat("_BumpScale",.65f);rockMaterial.EnableKeyword("_NORMALMAP");EditorUtility.SetDirty(rockMaterial);
string gravelPath=Dir+"/Mountain Gravel.terrainlayer";var gravel=AssetDatabase.LoadAssetAtPath<TerrainLayer>(gravelPath);if(!gravel){gravel=new TerrainLayer{name="Mountain soil and loose stones",tileSize=new Vector2(3.2f,3.2f),diffuseTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Scenes/Oasis/Art/Environment/Textures/Gravel_01_T_A.png"),smoothness=.04f};AssetDatabase.CreateAsset(gravel,gravelPath);}data.terrainLayers=new[]{baseline.terrainLayers[0],baseline.terrainLayers[1],gravel};var heights=baseline.GetHeights(0,0,513,513);float maximumDelta=0;
for(int z=0;z<513;z++)for(int x=0;x<513;x++){int hx=Mathf.Min(x,511),hz=Mathf.Min(z,511);if(data.IsHole(hx,hz))continue;float wx=terrain.transform.position.x+x/512f*data.size.x,wz=terrain.transform.position.z+z/512f*data.size.z;float distance=Distance(new Vector2(wx,wz),line);float mask=Mathf.SmoothStep(0,1,Mathf.InverseLerp(5,16,distance))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(35,43,distance)));float ridge=1-Mathf.Abs(Mathf.PerlinNoise(wx/9+28,wz/9+61)*2-1);float channel=Mathf.Pow(Mathf.PerlinNoise(wx/17+79,wz/17+16),3);float delta=((ridge-.52f)*5+(Mathf.PerlinNoise(wx/29+15,wz/29+39)-.5f)*3-channel*2)*mask;maximumDelta=Mathf.Max(maximumDelta,Mathf.Abs(delta));heights[z,x]=Mathf.Max(.01f,heights[z,x]+delta/data.size.y);}data.SetHeights(0,0,heights);terrain.Flush();
int shifted=0;var meshes=new HashSet<Mesh>();foreach(var filter in root.GetComponentsInChildren<MeshFilter>(true)){var mesh=filter.sharedMesh;if(!mesh||!meshes.Add(mesh))continue;var vertices=mesh.vertices;bool vegetation=filter.transform.parent&&(filter.transform.parent.name.StartsWith("Pine_")||filter.transform.parent.name.StartsWith("Shrub_"));int stride=filter.name=="Detailed"?12:8;if(vegetation){for(int start=0;start<vertices.Length;start+=stride){int count=Mathf.Min(stride,vertices.Length-start);var anchor=Vector3.zero;for(int j=0;j<count;j++)anchor+=filter.transform.TransformPoint(vertices[start+j]);anchor/=count;float delta=Height(data,terrain.transform.position,anchor)-Height(old,terrain.transform.position,anchor);for(int j=0;j<count;j++)vertices[start+j].y+=delta;}}else{for(int j=0;j<vertices.Length;j++){var p=filter.transform.TransformPoint(vertices[j]);vertices[j].y+=Height(data,terrain.transform.position,p)-Height(old,terrain.transform.position,p);}}mesh.vertices=vertices;if(!vegetation)mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);shifted++;}UnityEngine.Object.DestroyImmediate(old);
var alpha=new float[512,512,3];for(int z=0;z<512;z++)for(int x=0;x<512;x++){float u=(x+.5f)/512,v=(z+.5f)/512;float wx=terrain.transform.position.x+u*data.size.x,wz=terrain.transform.position.z+v*data.size.z;float distance=Distance(new Vector2(wx,wz),line);float slope=data.GetSteepness(u,v);float patch=Mathf.PerlinNoise(wx/10+16,wz/10+51);float rock=Mathf.Lerp(.12f,.8f,Mathf.InverseLerp(20,62,slope));rock*=Mathf.Lerp(.7f,1.2f,patch);float soil=Mathf.Lerp(.1f,.66f,1-Mathf.InverseLerp(22,58,slope));soil*=.5f+.5f*Mathf.PerlinNoise(wx/7+49,wz/7+79);if(distance<9)soil=Mathf.Max(soil,.52f);float grass=Mathf.Max(.08f,(1-rock-soil)*(.5f+.6f*Mathf.PerlinNoise(wx/16+31,wz/16+22)));float sum=rock+soil+grass;alpha[z,x,0]=rock/sum;alpha[z,x,1]=grass/sum;alpha[z,x,2]=soil/sum;}data.SetAlphamaps(0,0,alpha);data.SetBaseMapDirty();terrain.Flush();EditorUtility.SetDirty(data);
foreach(var lod in root.GetComponentsInChildren<LODGroup>())lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAssetAndConnect(root,Dir+"/Coastal Rocky Terrain.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(812,32,190),new Vector3(852,48,210),"Mountain-Surface-Final-Closeup"});capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Mountain-Surface-Final-Road-Level"});log.AppendLine("SUCCESS native Terrain erosion and ledges; maximum surface displacement="+maximumDelta+"m; 3 blended surface layers (rock, grass, loose-stone soil); cliff normal relief; native 513 heightmap retained; vegetation anchors retained in XZ and grounded to revised terrain; updated meshes="+shifted+"; shader errors="+ShaderUtil.GetShaderMessages(terrain.materialTemplate.shader).Count(m=>m.severity.ToString()=="Error"));}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/CoastalSurfaceFinishReport.txt",log.ToString());}}
